// B"H
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import MerkavaExecutor from "../../scripts/awtsmoos/MerkavaExecutor/merkavaexecutor.cjs";
import { readMd2 } from "./core/md2Reader.js";
import { buildNativeBrowserC } from "./core/nativeBrowserSource.js";
import { buildLauncherC } from "./core/launcherSource.js";
import { compile } from "../compiler/compiler.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const appFiles = {
  "/index.html": fs.readFileSync(path.join(here, "samples/frontend.html"), "utf8"),
  "/app.js": fs.readFileSync(path.join(here, "samples/app.js"), "utf8")
};
const shellFiles = {
  "/browser-shell.html": fs.readFileSync(path.join(here, "samples/browser-shell.html"), "utf8"),
  "/browser-shell.js": fs.readFileSync(path.join(here, "samples/browser-shell.js"), "utf8")
};
const bundle = await MerkavaExecutor.bundleEntry({ entry: "/index.html", files: appFiles });
const shellBundle = await MerkavaExecutor.bundleEntry({ entry: "/browser-shell.html", files: shellFiles });
const binary = bundle.binary;
const md2 = readMd2(binary);
if (!md2.ok) throw new Error("Merkava did not produce MD2 bytecode.");
const shellMd2 = readMd2(shellBundle.binary);
if (!shellMd2.ok) throw new Error("Merkava shell did not produce MD2 bytecode.");

const outDir = path.join(here, "dist");
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, "sample.md2"), Buffer.from(binary));
fs.writeFileSync(path.join(outDir, "browser-shell.md2"), Buffer.from(shellBundle.binary));
fs.writeFileSync(path.join(outDir, "native-browser-seed.c"), buildNativeBrowserC(binary, shellBundle.binary));
fs.writeFileSync(path.join(outDir, "merkavaapp-launcher.c"), buildLauncherC());
const exe = compile(buildLauncherC(), "c");
fs.writeFileSync(path.join(outDir, "merkavaapp.exe"), Buffer.from(await exe.arrayBuffer()));
console.log(JSON.stringify({ ok: true, bytes: binary.length, shellBytes: shellBundle.binary.length, section: md2.section, outDir }, null, 2));

